import { Kafka } from 'kafkajs';

const kafka = new Kafka({ brokers: ['kafka-broker-1:9092'] });

export const consumer = kafka.consumer({
  groupId: 'order-processing-group',
  // Cooperative Sticky Assignor prevents stop-the-world rebalance pauses
  partitionAssigners: [
    // In Kafka Java client: org.apache.kafka.clients.consumer.CooperativeStickyAssignor
  ],
  sessionTimeout: 45000,      // 45s heartbeat timeout
  maxPollInterval: 300000,    // 5 minutes max processing window per batch
});
